// domain — pure rules, imports nothing from UI
export function applyDiscount(cents: number, pct: number): number {
  if (pct < 0 || pct > 100) throw new Error("invalid discount")
  return Math.round(cents * (1 - pct / 100))
}

// UI — calls domain, never the reverse
const total = computed(() => applyDiscount(cents.value, pct.value))
